class UserState extends GraftState {
  String name = 'Alice';
  int points = 0;

  @override
  GraftProps get props => propsOf(name, points);
}

class UserGraft extends Graft<UserState> {
  UserGraft() : super(UserState());

  void addPoint() {
    state
      ..points += 1
      ..update();
  }
}
